class Solution {
public:
    ListNode* removeElements(ListNode* head, int val) {
        ListNode dummy(0), *prev = &dummy;
        dummy.next = head;
        while (head) {
            if (head->val == val) prev->next = head->next;
            else prev = head;
            head = head->next;
        }
        return dummy.next;
    }
};
